head.script:
scwin.onpageload = function() {
	window.msgCnt = 0;
};

scwin.fn_msg = function(){
    //debugger;
    var msg = "";
    var invalidType = this.getType(); 
    console.log("invalidType ==>" + invalidType); 
    if (invalidType == "mandatory") {
        msg = "Enter a date. 날짜를 입력하세요!! ";
    } else {
        msg = "Invalid date. 날짜 형식을 확인하세요!!";
    }
    //alert(msg); 
	window.msgCnt++;
	console.log(window.msgCnt);
}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'wq_uuid_5__date_input', 'key-sequence', {
			sequence: '230399'
		});
	}
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'wq_uuid_5__date_input', 'key-combo', {
			combo: 'ENTER'
		});
	}	
	scwin.checkVal = function() {
		return window.msgCnt == 1;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();

;
